def shrink_types(types, max_typed_dict_size):
    types_list = list(types)
    if not types_list:
        return Any

    # Separate typed dicts from other types
    typed_dicts = [t for t in types_list if is_anonymous_typed_dict(t)]
    non_typed_dicts = [t for t in types_list if not is_anonymous_typed_dict(t)]

    result_types = list(non_typed_dicts)

    if typed_dicts:
        shrunk_typed_dict = shrink_typed_dict_types(typed_dicts, max_typed_dict_size)
        result_types.append(shrunk_typed_dict)

    if not result_types:
        return Any

    # Deduplicate types
    unique_types = []
    for t in result_types:
        if not any(types_equal(t, u) for u in unique_types):
            unique_types.append(t)

    if len(unique_types) == 1:
        result = unique_types[0]
    else:
        result = Union[tuple(unique_types)]

    return DEFAULT_REWRITER.rewrite(result)
